int gw_mex_bridge_is_native_data(uint32_t native_addr, uint32_t size)
{
    uint32_t lo = 0;
    uint32_t hi = (uint32_t)(sizeof gw_mex_bridge_native_data /
                            sizeof gw_mex_bridge_native_data[0]);
    /* Cheap reject first: almost every address asked about is a guest one. */
    if (native_addr < 0x105E4EE0u || native_addr >= 0x1087CA7Cu) {
        return 0;
    }
    while (lo < hi) {
        uint32_t mid = lo + (hi - lo) / 2;
        if (native_addr >= gw_mex_bridge_native_data[mid].hi) {
            lo = mid + 1;
        } else if (native_addr < gw_mex_bridge_native_data[mid].lo) {
            hi = mid;
        } else {
            /* The whole access must stay inside the run, so a multi-byte load
             * cannot walk off the end of a global into whatever follows it. */
            return (uint64_t)native_addr + size <=
                   (uint64_t)gw_mex_bridge_native_data[mid].hi;
        }
    }
    return 0;
}
